task difference(n: int) returns (r: int)
  requires n >= 0
  ensures r == sum_cubes(n) - sum_naturals(n)
spec fun sum_naturals(k: int): int
  decreases k
= if k <= 0 then 0 else k + sum_naturals(k - 1)
spec fun sum_cubes(k: int): int
  decreases k
= if k <= 0 then 0 else k * k * k + sum_cubes(k - 1)
{
  var sum_n: int := 0;
  var sum_c: int := 0;
  var i: int := 1;
  while i <= n
    invariant 1 <= i and i <= n + 1
    invariant sum_n == sum_naturals(i - 1)
    invariant sum_c == sum_cubes(i - 1)
    decreases n - i + 1
  {
    sum_n := sum_n + i;
    sum_c := sum_c + i * i * i;
    i := i + 1;
  }
  r := sum_c - sum_n;
}
