  ensures r == sum_fourth_power_odd(n)
spec fun sum_fourth_power_odd(k: int): int
  decreases k
= if k <= 0 then 0 else (2 * k - 1) * (2 * k - 1) * (2 * k - 1) * (2 * k - 1) + sum_fourth_power_odd(k - 1)
